/* Personal decks, handwriting replay, optional camp cosmetics, and user-started voice search. */
let labPaper=null,labPaperTimer=null;
function labCanonicalWord(zh){const compact=String(zh).normalize('NFKC').replace(/[^\u3400-\u9fff]/g,''),cw=typeof CW_WORDS!=='undefined'&&CW_WORDS.find(w=>w.s===compact||w.t===compact);if(cw)return cw.s;const word=Object.values(WORDS).flat().find(w=>w[0]===compact||courseTraditional(w[0])===compact);return word?.[0]||compact}
function labPreviewSceneWords(){const q=labCurrent();if(!q?.scene||labRun.feedback)return;labRun.usedHint=true;labCheckpoint();const zh=q.scene.zh,seen=new Set(),words=[...(WORDS[labRun.lesson]||[]),...Object.values(WORDS).flat(),...CW_WORDS.map(w=>[w.s,w.p,w.en])].filter(w=>zh.includes(w[0])&&!seen.has(w[0])&&seen.add(w[0])).sort((a,b)=>b[0].length-a[0].length).slice(0,5);if(!words.length)for(const ch of [...new Set([...zh])]){const c=cardByChar[ch];if(c)words.push([ch,c.pinyin,c.meaning]);if(words.length>=5)break}studyModal(`<h2>Words in this scene</h2><p class="small muted">This preview counts as help for the current answer. It does not mark words learned.</p><div class="lab-word-board">${words.map(([word,py,en])=>`<div><strong lang="zh">${labClickable(labZh(word))}</strong><p>${esc(py)} · ${esc(en)}</p><button class="btn" data-word="${esc(word)}" onclick="speak(this.dataset.word)">${icon('sound')} Word audio</button></div>`).join('')}</div>`)}
function labOpenPaper(ch){const c=ch?courseCard(ch):uniqueCards(labLesson())[0];if(!c)return;labStop();const old=labData().paper;labPaper=old?.character===c.character&&old.course===selectedCourseId?old:{course:selectedCourseId,character:c.character,pos:0,strokes:[],freeCopies:null,model:false,started:0,elapsed:0,timed:false};labData().paper=labPaper;navigate('labwrite')}
function renderLabPaper(){
 setPracticeViewport(true);if(!labPaper||labPaper.course!==selectedCourseId)labPaper=labData().paper?.course===selectedCourseId?labData().paper:null;if(!labPaper)return labOpenPaper();
 const c=courseCard(labPaper.character),elapsed=labPaper.elapsed+(labPaper.timed?Date.now()-labPaper.started:0);
 $('view').innerHTML=`<div class="lab-run lab-paper-run"><header class="lab-run-top"><button class="textbtn" onclick="labCheckpoint();navigate('lab')">${icon('back')} Practice</button><span>Writing lab · free writing &amp; replay</span><button class="iconbtn" aria-label="Writing shortcuts" onclick="showPracticeShortcuts()">${icon('help')}</button></header><div></div><section class="lab-exercise"><div class="lab-paper-header"><div><h2>${esc(c.pinyin)}</h2><p>${esc(c.meaning)}</p></div><label>Character<select onchange="labOpenPaper(this.value)">${uniqueCards().map(card=>`<option value="${card.character}" ${card.character===c.character?'selected':''}>${esc(han(card)+' · '+card.pinyin)}</option>`).join('')}</select></label></div><div class="lab-paper-stage">${labPaper.model?`<div class="lab-model-overlay" aria-hidden="true" lang="zh">${esc(han(c))}</div>`:''}<canvas id="write-canvas" tabindex="0" aria-label="Free handwriting and replay pad"></canvas></div><div class="lab-paper-controls"><button class="btn" onclick="labPaper.model=!labPaper.model;renderLabPaper();save()">${labPaper.model?'Hide':'Overlay'} model</button><button class="btn" onclick="labReplay()">${icon('play')} Replay</button><button class="btn" onclick="if(labArchiveDrawing())toast('Drawing saved to your mistake album')">Save to album</button></div><details class="lab-paper-details"><summary>Inspect strokes &amp; measure your pace</summary><label class="lab-stroke-scrub">Inspect your strokes<input type="range" id="lab-stroke-range" min="0" max="${labPaper.strokes.length}" value="${labPaper.strokes.length}" aria-label="Number of your strokes to display" oninput="labPaint(Number(this.value));$('lab-replay-status').textContent='Showing '+this.value+' of '+labPaper.strokes.length+' strokes'"></label><p id="lab-replay-status" class="small muted" role="status">${labPaper.strokes.length} strokes. The translucent font model is a spacing guide. Use checked writing for stroke validation.</p><p class="small muted">Optional timer · speed does not affect rewards.</p><div class="row"><button class="btn" onclick="labTimerToggle()">${labPaper.timed?'Pause':'Start'} timer</button><output id="lab-writing-time">${(elapsed/1000).toFixed(1)} seconds</output></div></details><button class="textbtn" onclick="startWrittenChapter('${labLesson()}')">Switch to checked writing ${icon('arrow')}</button></section><footer class="lab-run-actions">${inkFreeControls()}</footer></div>`;
 inkBindCanvas($('write-canvas'),false);if(labPaper.timed)labTimerTick();
}
function labPaint(count=Infinity){const canvas=$('write-canvas');if(!canvas||!labPaper)return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--line');ctx.lineWidth=1;ctx.setLineDash([5,5]);ctx.beginPath();ctx.moveTo(w/2,0);ctx.lineTo(w/2,h);ctx.moveTo(0,h/2);ctx.lineTo(w,h/2);ctx.stroke();ctx.setLineDash([]);ctx.strokeStyle=getComputedStyle(document.documentElement).getPropertyValue('--ink');ctx.lineWidth=3*(window.devicePixelRatio||1);ctx.lineCap='round';ctx.lineJoin='round';for(const points of labPaper.strokes.slice(0,count)){if(!points.length)continue;ctx.beginPath();ctx.moveTo(points[0][0]*w,points[0][1]*h);if(points.length===1)ctx.lineTo(points[0][0]*w+.5,points[0][1]*h+.5);for(const p of points.slice(1))ctx.lineTo(p[0]*w,p[1]*h);ctx.stroke()}}
function labReplay(){if(!labPaper?.strokes.length)return toast('Write something first.');const token=++labReplayToken,paper=labPaper;let frame=0;const step=()=>{if(token!==labReplayToken||currentView!=='labwrite'||labPaper!==paper)return;labPaint(frame);const status=$('lab-replay-status');if(status)status.textContent='Stroke '+frame+' / '+paper.strokes.length;if(frame++<paper.strokes.length)setTimeout(step,160)};step()}
function labArchiveDrawing(){if(!labPaper?.strokes.length){toast('Write something before saving a drawing.');return false}const d=labData(),ch=labPaper.character,m=d.mistakes[ch]??={count:0,last:Date.now(),skill:'writing',note:'',drawing:[],model:labPaper.model};const drawing=inkSafeStrokes(labPaper.strokes),points=drawing.reduce((n,s)=>n+s.length,0),otherPoints=Object.entries(d.mistakes).filter(([key])=>key!==ch).reduce((n,[,v])=>n+(v.drawing||[]).reduce((count,stroke)=>count+stroke.length,0),0);if(points+otherPoints>12000)return toast('Your drawing album is full. Remove a saved drawing before adding another.');m.drawing=drawing;m.last=Date.now();m.model=labPaper.model;save();return true}
function labTimerToggle(){if(!labPaper)return;if(labPaper.timed)labTimerStop();else{labPaper.started=Date.now();labPaper.timed=true}renderLabPaper();save()}
function labTimerStop(){clearTimeout(labPaperTimer);labPaperTimer=null;if(labPaper?.timed){labPaper.elapsed=Math.min(3600000,labPaper.elapsed+Date.now()-labPaper.started);labPaper.timed=false;save()}}
function labTimerTick(){clearTimeout(labPaperTimer);const paper=labPaper;if(!paper?.timed||currentView!=='labwrite')return;const el=$('lab-writing-time');if(el)el.textContent=((paper.elapsed+Date.now()-paper.started)/1000).toFixed(1)+' seconds';labPaperTimer=setTimeout(()=>{if(labPaper===paper)labTimerTick()},250)}
function renderLabDecks(){setPracticeViewport(false);$('view').innerHTML=labShell('Your study decks',`<p class="muted">Add vocabulary from your class or interests. Personal word knowledge stays separate from character recognition and the common-word collection.</p><div class="lab-decks">${labData().decks.map(d=>`<article><div><h2>${esc(d.name)}</h2><p>${d.entries.length} words</p></div><div class="row"><button class="btn primary" data-id="${d.id}" onclick="labStart('deck',labLesson(),{deck:this.dataset.id})">Practice</button><button class="btn" data-id="${d.id}" onclick="labPreviewDeck(this.dataset.id)">Browse</button><button class="textbtn" data-id="${d.id}" onclick="labExportDeck(this.dataset.id)">Export</button><button class="textbtn" data-id="${d.id}" onclick="labDeleteDeck(this.dataset.id)">Delete</button></div></article>`).join('')||'<p>No personal decks yet. Add one below.</p>'}</div><section class="lab-deck-import"><h2>Add a deck</h2><label>Deck name<input class="input" id="lab-deck-name" maxlength="60" placeholder="My Chinese class"></label><label>Vocabulary<textarea id="lab-deck-text" rows="7" placeholder="汉字, pinyin, English\n朋友, péngyou, friend\n学校, xuéxiào, school"></textarea></label><p class="small muted">Paste CSV/TSV with Chinese, pinyin, and English columns. Optional traditional and context columns are supported. JSON exports can be imported too. Up to 100 entries per deck; 10 decks.</p><div class="row"><button class="btn primary" onclick="labImportDeck($('lab-deck-text').value,$('lab-deck-name').value)">Add vocabulary</button><button class="btn" onclick="labImportDeckFile()">Choose CSV / TSV / JSON</button></div><p id="lab-deck-error" role="status"></p></section>`,'labdecks')}
function labCsvRows(text,delimiter){const rows=[],row=[];let field='',quoted=false;for(let i=0;i<text.length;i++){const ch=text[i];if(ch==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(!quoted&&(ch===delimiter||ch==='\n')){row.push(field.trim());field='';if(ch==='\n'){if(row.some(Boolean))rows.push(row.splice(0));else row.length=0}}else if(ch!=='\r')field+=ch}if(quoted)throw Error('A quoted field is missing its closing quote.');row.push(field.trim());if(row.some(Boolean))rows.push(row);return rows}
function labParseDeck(text,name){if(typeof text!=='string'||text.length>200000)throw Error('Use a deck file smaller than 200 KB.');text=text.replace(/^\uFEFF/,'').trim();if(!text)throw Error('Add some vocabulary first.');let entries,title=name;if(text[0]==='['||text[0]==='{'){let parsed;try{parsed=JSON.parse(text)}catch{throw Error('That JSON file could not be read.')}entries=Array.isArray(parsed)?parsed:parsed.entries;title=title||parsed.name;if(!Array.isArray(entries))throw Error('JSON needs an entries array.');entries=entries.map((w,i)=>{if(!w||typeof w!=='object')throw Error('Entry '+(i+1)+' must contain Chinese, pinyin, and English fields.');return {zh:w.zh||w.simplified||w.character,traditional:w.traditional,py:w.py||w.pinyin,en:w.en||w.english||w.meaning,context:w.context}})}else{const rows=labCsvRows(text,text.split('\n')[0].includes('\t')?'\t':','),headers=rows[0]?.map(x=>x.toLowerCase()),hasHeader=headers?.some(x=>['zh','chinese','汉字','漢字','中文','simplified','character','word'].includes(x));let columns={zh:0,py:1,en:2,traditional:3,context:4};if(hasHeader){rows.shift();const aliases={zh:['zh','chinese','汉字','漢字','中文','simplified','character','word'],py:['py','pinyin'],en:['en','english','meaning'],traditional:['traditional','繁体'],context:['context','example']};columns=Object.fromEntries(Object.entries(aliases).map(([key,names])=>[key,headers.findIndex(x=>names.includes(x))]))}entries=rows.map(row=>Object.fromEntries(Object.entries(columns).map(([key,index])=>[key,index>=0?row[index]:undefined])))}if(!entries.length||entries.length>100)throw Error('Use between 1 and 100 entries per deck.');const seen=new Set();entries=entries.map((w,i)=>{if(typeof w.zh!=='string'||typeof w.en!=='string'||!w.zh.trim()||!w.en.trim()||!/[\u3400-\u9fff]/.test(w.zh))throw Error('Entry '+(i+1)+' needs Chinese characters and an English meaning.');const key=w.zh.trim()+'|'+w.en.trim();if(seen.has(key))return null;seen.add(key);return w}).filter(Boolean);return labValidateDeck({id:'deck-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),name:title||'My vocabulary',entries,created:Date.now()})}
function labImportDeck(text,name){try{if(labData().decks.length>=10)throw Error('Your 10 deck slots are full. Export or remove a deck before adding another.');const deck=labParseDeck(text,name);if(!deck)throw Error('No valid vocabulary was found.');labData().decks.push(deck);save();renderLabDecks();toast(deck.entries.length+' words added')}catch(e){const el=$('lab-deck-error');if(el)el.textContent=e.message;else toast(e.message)}}
function labImportDeckFile(){const input=document.createElement('input');input.type='file';input.accept='.csv,.tsv,.json,text/csv,text/tab-separated-values,application/json';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;if(file.size>200000)return toast('Use a vocabulary file smaller than 200 KB.');labImportDeck(await file.text(),$('lab-deck-name')?.value||file.name.replace(/\.[^.]+$/,''))};input.click()}
function labPreviewDeck(id){const d=labData().decks.find(x=>x.id===id);if(!d)return;studyModal(`<h2>${esc(d.name)}</h2><p>Browsing does not count as recall.</p><div class="lab-word-board">${d.entries.map(w=>`<div><strong lang="zh">${labClickable(labZh(w.zh,w.traditional))}</strong><p>${esc(w.py)} · ${esc(w.en)}</p>${w.context?`<p>${labClickable(labZh(w.context))}</p>`:''}<button class="btn" data-word="${esc(w.zh)}" onclick="speak(this.dataset.word)">${icon('sound')} Word audio</button>${w.context?`<button class="btn" data-sentence="${esc(w.context)}" onclick="speak(this.dataset.sentence)">Sentence audio</button>`:''}</div>`).join('')}</div>`)}
function labExportDeck(id){const d=labData().decks.find(x=>x.id===id);if(!d)return;const blob=new Blob([JSON.stringify({name:d.name,entries:d.entries},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Chinese_vocabulary_'+d.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function labDeleteDeck(id){const d=labData().decks.find(x=>x.id===id);if(!d||!confirm('Delete “'+d.name+'”? Export it first if you want a copy. Other learning progress stays.'))return;labData().decks=labData().decks.filter(x=>x.id!==id);for(const [course,r]of Object.entries(labData().runs))if(r?.deck===id)delete labData().runs[course];save();renderLabDecks()}
function labVoiceSearch(){const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Recognition)return toast('Speech input is unavailable in this browser. Use Quick Find to type a word.');labStop();const token=labVoiceToken,course=selectedCourseId,view=currentView,recognition=new Recognition();labVoice=recognition;recognition.lang=state.settings.script==='traditional'?'zh-TW':'zh-CN';recognition.interimResults=false;recognition.continuous=false;recognition.onresult=event=>{if(token!==labVoiceToken||course!==selectedCourseId||currentView!==view)return;const heard=event.results?.[0]?.[0]?.transcript;if(!heard)return;labVoiceToken++;try{recognition.stop?.()}catch{}labVoice=null;openQuickLookup();const input=$('flow-lookup-input');if(input)input.value=heard;updateQuickLookup(heard)};recognition.onerror=event=>{if(token===labVoiceToken)toast(event.error==='not-allowed'?'Microphone access was denied. You can type in Quick Find.':'Could not hear a word. Try again or type it.');labVoice=null};recognition.onend=()=>{if(token===labVoiceToken)labVoice=null};try{recognition.start();toast('Listening for a word…')}catch{labVoice=null;toast('Microphone could not start. Try Quick Find instead.')}}
function labWeek(){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()-((d.getDay()+6)%7));return dayKey(d)}
function labWeeklyMissions(){const start=labWeek(),days=Object.entries(labData().days).filter(([date])=>date>=start),skills=new Set(days.flatMap(([,d])=>d.skills)),independent=days.reduce((n,[,d])=>n+d.keys.length,0),active=days.filter(([,d])=>d.keys.length>0).length;return [{id:'variety',name:'Practice three skills',value:skills.size,goal:3,reward:3},{id:'return',name:'Recall on three days',value:active,goal:3,reward:4},{id:'twenty',name:'Twenty independent checks',value:independent,goal:20,reward:5}]}
function labOpenWeekly(){navigate('labcamp');$('lab-weekly')?.scrollIntoView({behavior:state.settings.animations?'smooth':'instant'})}
function labClaimMission(id){const mission=labWeeklyMissions().find(m=>m.id===id),key='week:'+labWeek()+':'+id;if(!mission||mission.value<mission.goal||labData().claimed.includes(key))return false;labData().claimed.push(key);labData().stamps+=mission.reward;save();renderLabCamp();return true}
function labBuy(id){const item=LAB_SHOP.find(x=>x.id===id),d=labData();if(!item||d.unlocked.includes(id)||d.stamps-d.spent<item.cost)return false;d.spent+=item.cost;d.unlocked.push(id);save();renderLabCamp();return true}
function labEquip(id){const d=labData();if(!d.unlocked.includes(id))return;const item=LAB_SHOP.find(x=>x.id===id);if(id==='grove'||item?.kind==='habitat')d.habitat=id;else if(id==='plain'||item?.kind==='skin')d.skin=id;else if(item?.kind==='decor')d.decor=d.decor.includes(id)?d.decor.filter(x=>x!==id):[...d.decor,id];save();labApplySkin();renderLabCamp()}
function labApplySkin(){const skin=labData().skin;document.body.dataset.practiceSkin=skin}
function labActiveAbilities(){if(!state.companion.enabled||!starterData())return [];return LAB_ABILITIES.filter(a=>(labData().abilities[state.companion.starter]||[]).includes(a.id))}
function labLearnAbility(id){const ability=LAB_ABILITIES.find(a=>a.id===id);if(!ability||!state.companion.enabled||!starterData()||labSkillSummary(ability.skill).items<ability.need)return;const skills=labData().abilities[state.companion.starter]??=[];if(!skills.includes(id))skills.push(id);save();renderLabCamp()}
function labUseAbility(id){const ability=labActiveAbilities().find(a=>a.id===id),q=labCurrent();if(!ability||!q||q.skill!==ability.skill||labRun.abilityUsed||labRun.feedback)return;labRun.abilityUsed=true;labHelp();toast(ability.name+' used. This answer counts as helped.')}
function renderLabCamp(){setPracticeViewport(false);const d=labData(),starter=state.companion.enabled&&starterData(),week=labWeek(),balance=d.stamps-d.spent,events=[{need:d.history.length>=1,title:'First outing',text:'Your companion found a quiet clearing after your first chapter run.'},{need:d.history.filter(r=>['story','comic','scene','dialogue'].includes(r.mode)).length>=2,title:'A familiar path',text:'The signs on the path are beginning to look familiar. Your companion waits beside the next one.'},{need:d.retained.length>=3,title:'Roots that hold',text:'Three things remembered across a week. A small new shoot has appeared beside the camp.'}];$('view').innerHTML=labShell(starter?'Your companion camp':'Weekly practice',`${starter?`<section class="lab-camp habitat-${d.habitat}"><div class="lab-camp-moon"></div><div class="lab-camp-hills"></div>${d.decor.includes('bamboo')?'<div class="lab-prop-bamboo" aria-label="Bamboo decoration">竹</div>':''}${d.decor.includes('lantern')?'<div class="lab-prop-lantern" aria-label="Paper lantern decoration">灯</div>':''}${d.decor.includes('stones')?'<div class="lab-prop-stones" aria-label="Stepping stones decoration"><i></i><i></i><i></i></div>':''}<button class="lab-camp-buddy" onclick="labCampReact()" aria-label="Interact with your companion">${companionReactionArt('happy')}</button><div class="lab-camp-name"><strong>${esc(starter.forms[state.companion.stage])}</strong><span>Level ${companionLevel()} · active companion</span></div><p id="lab-camp-reaction" role="status">Tap your companion.</p></section><div class="lab-inline"><button onclick="openCompanionSelection()">Your collection</button><button onclick="openJourney('badges')">Course badges</button></div>`:`<p>Companion mode is ${state.companion.enabled?'waiting for a starter':'off'}. Your study records and weekly missions remain available.</p><button class="btn" onclick="${state.companion.enabled?'openCompanionSelection()':"navigate('settings')"}">${state.companion.enabled?'Choose a companion':'Companion setting'}</button>`}<section class="lab-weekly" id="lab-weekly"><div class="lab-section-heading"><h2>This week’s missions</h2><span>Week of ${esc(week)}</span></div><div class="lab-three">${labWeeklyMissions().map(m=>{const claimed=d.claimed.includes('week:'+week+':'+m.id);return `<article><strong>${m.name}</strong><p>${Math.min(m.value,m.goal)} / ${m.goal}</p><div class="progress"><span style="width:${Math.min(100,m.value/m.goal*100)}%"></span></div><button class="btn" ${claimed||m.value<m.goal?'disabled':''} onclick="labClaimMission('${m.id}')">${claimed?'Collected':'Collect '+m.reward+' stamps'}</button></article>`}).join('')}</div><p class="small muted">Independent checks earn stamps, up to 20 per day. Repeated answers, browsing, and switching companions do not create extra stamps.</p></section>${starter?`<section class="lab-abilities"><h2>Companion abilities</h2><p class="small muted">Learn an ability through independent practice. Use one per run when you want a clue; it counts as help.</p><div class="lab-ability-grid">${LAB_ABILITIES.map(a=>{const learned=(d.abilities[state.companion.starter]||[]).includes(a.id),progress=labSkillSummary(a.skill).items;return `<article><h3>${a.name}</h3><p>${a.description}</p><small>${Math.min(progress,a.need)} / ${a.need} distinct ${a.skill} answers</small><button class="btn" ${learned||progress<a.need?'disabled':''} onclick="labLearnAbility('${a.id}')">${learned?'Learned':'Learn ability'}</button></article>`}).join('')}</div></section>`:''}<section class="lab-shop"><div class="lab-section-heading"><h2>Camp &amp; surfaces</h2><span>${balance} stamps available</span></div><div class="lab-shop-grid">${[{id:'grove',kind:'habitat',name:'Jade grove',cost:0},{id:'plain',kind:'skin',name:'Original surface',cost:0},...LAB_SHOP].map(item=>{const owned=d.unlocked.includes(item.id),equipped=d.habitat===item.id||d.skin===item.id||d.decor.includes(item.id);return `<article class="lab-shop-item shop-${item.id}"><span class="lab-shop-swatch"></span><strong>${item.name}</strong><small>${item.kind==='skin'?'Works with your saved color palette':item.kind==='decor'?'Camp decoration':'Companion habitat'}</small><button class="btn" ${!owned&&balance<item.cost?'disabled':''} onclick="${owned?'labEquip':'labBuy'}('${item.id}')">${owned?(equipped?(item.kind==='decor'?'Remove':'Selected'):'Use'):item.cost+' stamps'}</button></article>`}).join('')}</div></section>${starter?`<details class="lab-more"><summary>Companion adventures</summary><div class="lab-events">${events.map(e=>`<article class="${e.need?'unlocked':'locked'}"><h3>${e.need?e.title:'A path ahead'}</h3><p>${e.need?e.text:'Keep practicing across different skills and return on later days to discover this scene.'}</p></article>`).join('')}</div></details>`:''}`,'labcamp');labApplySkin()}
function labCampReact(){const el=$('lab-camp-reaction');if(!el)return;const lines=['Let’s build a character together.','Choose a story for our next outing.','I remember that tricky shape. Do you?','Ready for another chapter run?'];el.textContent=lines[Math.floor(Math.random()*lines.length)];const art=$('view').querySelector('.lab-camp-buddy');if(art)art.innerHTML=companionReactionArt(['happy','thinking','celebrate'][Math.floor(Math.random()*3)])}
